package com.nimbusbill.customer.repository; import com.nimbusbill.customer.entity.Invoice; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface InvoiceRepository extends JpaRepository<Invoice,UUID>{Optional<Invoice> findByBillingRunId(UUID billingRunId);List<Invoice> findByCustomerIdOrderByCreatedAtDesc(UUID customerId);List<Invoice> findByStatusAndDueDateBefore(String status,java.time.LocalDate date);@Query(value="select nextval('invoice_number_seq')",nativeQuery=true) Long nextNumber();}
